// StoreDefect is anything that can stand as a planted defect for a
// row — in practice a StoreHarness over the generated double.
type StoreDefect interface {
	Subject() (StoreSubject, error)
}

// BrokenStore names a planted defect.
//
// Sugar over the harness, because a defect IS a subject — one built to
// fail exactly one claim. Its own constructor is what keeps a proofs
// table readable beside a run's.
func BrokenStore[T Store](
	name string, build func() T,
) StoreHarness[T] {
	return StoreHarness[T]{
		Name: name, New: build,
	}
}

// StoreChecks is the table of this package's own checks.
type StoreChecks []StoreCheck

func (c StoreChecks) applyTo(rc *storeRunConfig) {
	rc.rows = append(rc.rows, c...)
}

// StoreCheck is one row. The body is a plain named function; which
// field it goes in decides what it receives.
type StoreCheck struct {
	// Method scopes Run's ID: "Touch" makes it Touch/<name>.
	// A body that fixes its own scope leaves this empty.
	Method string

	// Name is the ID's slug — the stable handle a drop and a rerun use.
	Name string

	// Claim is the sentence the manifest records and the report reads
	// out. A claim wider than its assertion is the one failure this
	// surface cannot catch for you.
	Claim string

	// Exactly one body.
	//
	// Run gets one fresh instance, which is nearly every check. RunWith
	// gets the subject itself, for a claim one instance cannot state:
	// build two, move the clock, induce a failure.
	//
	// Both take the fixture whether or not any DERIVED check draws one,
	// so the row seam has one shape across every package and a fixture
	// that later grows a field does not change a signature consumers
	// have already written against.
	Run     func(tb testing.TB, s Store, fx StoreFixture)
	RunWith func(tb testing.TB, sub StoreSubject, fx StoreFixture)

	// Class buckets the report. Empty means hand-written.
	Class suite.Class

	// Needs declares capabilities. A harness that cannot meet one fails
	// this check by name with the fix in the message, never skips — a
	// check that skipped for want of wiring reads as coverage.
	Needs suite.Caps

	// ProvenBy is the planted defect that fails this check and nothing
	// else. Setting it is the claim AND the evidence: the row reports
	// Proven, and ProveStore fails unless the defect turns the check
	// red. ProvenReason, when set, is a substring that red must contain,
	// so a defect dying on an incidental guard stops counting as one.
	//
	// Argued records why no defect can be constructed — the honest third
	// answer. At most one of ProvenBy and Argued; neither means unproven,
	// which is what the report says about a check nobody has driven
	// against anything.
	ProvenBy     StoreDefect
	ProvenReason string
	Argued       string
}

// storeMethods is the interface's method set, for naming a Method typo
// at run start.
//
// A misspelled method starts with a capital too, so the ID grammar alone
// would file a check under a method that does not exist and report it
// under a path no drop can name.
var storeMethods = suite.NewNameSet("Store", storeTouch, storeSeen, storeMove, storeAt, storeEmit, storeCount)

// bind lowers one row onto the runtime check type, against the run's own
// fixture — which is what lets a row's body draw what the run draws.
func (c StoreCheck) bind(
	fx StoreFixture,
) (suite.Check[Store], error) {
	out := suite.Check[Store]{
		Claim: c.Claim, Class: c.Class, Needs: c.Needs,
	}
	if out.Class == "" {
		out.Class = suite.ClassHandWritten
	}

	var err error
	bodies := 0
	if c.Run != nil {
		bodies++
		if out.ID, err = suite.RowID("Run", c.Method, c.Name, storeMethods); err != nil {
			return out, err
		}
		run := c.Run
		out.Run = func(tb testing.TB, s Store) {
			run(tb, s, fx)
		}
	}
	if c.RunWith != nil {
		bodies++
		out.ID = suite.HandRowID(c.Name)
		rw := c.RunWith
		out.RunWith = func(tb testing.TB, sub StoreSubject) {
			rw(tb, sub, fx)
		}
	}
	if err := suite.OneBody(c.Name, bodies, "Run, RunWith"); err != nil {
		return out, err
	}
	if c.Method != "" && c.Run == nil {
		return out, fmt.Errorf(
			"check %q sets Method, but its body fixes its own scope; drop Method", c.Name)
	}
	if out.Falsifiable, err = suite.Falsify(c.Name, c.ProvenBy != nil, c.Argued); err != nil {
		return out, err
	}
	return out, nil
}

// RunStore runs every check — generated and yours — against every
// harness.
//
//	RunStore(t,
//		StoreHarness[*InMemory]{Name: "in-memory", New: NewInMemory},
//		StoreSuite.Without(StoreSuite.Checks.Touch.Smoke()),
//	)
func RunStore(
	t *testing.T, opts ...StoreRunOpt,
) {
	t.Helper()
	var rc storeRunConfig
	for _, o := range opts {
		o.applyTo(&rc)
	}
	fx := storeNewFixture()
	for _, row := range rc.rows {
		rc.AddCheck(row.bind(fx))
	}
	// Between folding and running: a misused run reports every fix it
	// needs and executes nothing, rather than reporting one and leaving
	// the rest to be found a cycle at a time.
	rc.Fail(t, "RunStore")
	suite.Run(t,
		storeSuite(fx).With(rc.Extra...).Without(rc.Drops...),
		rc.Subjects...)
}

// ProveStore drives each of your rows against the defect it names.
//
// A row with no ProvenBy is not skipped — it is held to saying why
// through Argued. The parity gate refuses a Proven claim with no
// evidence and evidence for a claim nobody made, in both directions, so
// this is where "proven able to fail" stops being prose.
func ProveStore(
	t *testing.T, checks StoreChecks,
) {
	t.Helper()
	// The RUN's config, not the derived one: a check proven at default
	// pools carries no evidence about the pools a run actually uses.
	fx := storeNewFixture()
	bound := make([]suite.Check[Store], 0, len(checks))
	defects := prove.Defects[Store]{}
	for _, row := range checks {
		bd, err := row.bind(fx)
		if err != nil {
			t.Fatalf("ProveStore: %v", err)
		}
		bound = append(bound, bd)
		if row.ProvenBy == nil {
			continue
		}
		sub, err := row.ProvenBy.Subject()
		if err != nil {
			t.Fatalf("ProveStore: check %q: defect: %v", bd.ID, err)
		}
		defects[bd.ID] = prove.Defect[Store]{
			Subject: sub, Reason: row.ProvenReason,
		}
	}
	prove.All(t, bound, defects)
}

